import {V,Q,ports,busy,autoLinks} from './engine.js';
import {editBlockReason} from './editor-state.js';
export const externalLinks=(model,ids)=>model.links.filter(l=>ids.has(l.a)!==ids.has(l.b));
export function disconnectSelection(model,ids){const reason=editBlockReason(model,ids);if(reason)throw Error(reason);const removed=externalLinks(model,ids);model.links=model.links.filter(l=>ids.has(l.a)===ids.has(l.b));return removed.length;}
export function relocatedParts(model,ids,anchorId,proposal){const anchor=model.parts.find(p=>p.id===anchorId);if(!anchor||!ids.has(anchorId))throw Error('Choose a part in the selected section.');const delta=Q(proposal.part.quat).multiply(Q(anchor.quat).invert());return model.parts.filter(p=>ids.has(p.id)).map(p=>({...p,pos:V(p.pos).sub(V(anchor.pos)).applyQuaternion(delta).add(V(proposal.part.pos)).toArray(),quat:delta.clone().multiply(Q(p.quat)).toArray()}));}
export function attachRelocated(model,ids,anchorId,proposal){const reason=editBlockReason(model,ids);if(reason)throw Error(reason);if(externalLinks(model,ids).length)throw Error('Disconnect the selection first.');const link=proposal.link?{...proposal.link,b:anchorId}:null;if(link&&busy(model,anchorId,link.bp)&&!['shaft','teeth'].includes(link.bp))throw Error('This connection on the moving section is already occupied. Choose another part or socket.');const moved=relocatedParts(model,ids,anchorId,proposal);for(const next of moved){const p=model.parts.find(p=>p.id===next.id);p.pos=next.pos;p.quat=next.quat;}if(link)model.links.push(link);for(const p of moved)model.links.push(...autoLinks(model,p));return moved;
}
